{
  "packet_id": "H6-T03-3",
  "claim_id": "C020",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C020.component",
    "value": "Historical cases should be distinguished as supported prior approval, evidenced late or absent approval, or unresolved.",
    "scope": "An evidence-based historical classification. The mapping groups late and absent approval together and does not specify what evidence establishes absence or whether absence means before placement or altogether.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P017 supplies the three categories and requires unresolved status when evidence merely cannot be located. The annotation preserves the unspecified meaning and evidentiary standard for absence."
    }
  },
  "signal_basis": {
    "component_id": "C020.signal_basis",
    "value": "Compare order-placement timestamps with purchasing records, meeting minutes and delegated-authority forms to assess authorized approval before placement. Distinguish later retrieval of prior-approval evidence from approval granted afterward, and retain unresolved status when evidence cannot be located.",
    "scope": "Historical record review for each flagged order. Sufficiently specific, dated evidence supports prior approval; missing records alone do not establish absence, and later approval does not establish prior approval.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the historical comparison, evidence requirements, timing distinction and limits on interpreting unavailable records."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C020.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported classification claim."
    }
  },
  "rationale": "The record-review operation licenses distinguishing supported findings from unresolved cases. This claim prescribes evidence-sensitive categories without asserting that any particular order belongs in them. The unresolved category accommodates unavailable or inconclusive evidence.",
  "uncertainty": "The absence category remains underspecified, as the frozen claim acknowledges. This limits assigning cases to that category but does not defeat the bounded recommendation to distinguish evidentiary outcomes.",
  "anomalies": []
}
